import React, { useState, useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { ScrollToPlugin } from 'gsap/ScrollToPlugin';
import partListData from './part_list.json';
import PixiCanvas from './components/PixiCanvas';
import lottie from 'lottie-web';

gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);

function App() {
  // Form state
  const [selectedLine, setSelectedLine] = useState('');
  const [selectedPart, setSelectedPart] = useState('');
  const [production, setProduction] = useState('');
  const [availableParts, setAvailableParts] = useState([]);

  // UI state
  const [showSubmitButton, setShowSubmitButton] = useState(false);
  const [showScrollMessage, setShowScrollMessage] = useState(false);

  // Dimensions
  const [dimensions, setDimensions] = useState({ width: 400, height: 300 });

  // Frame scrub state (Section 1 & 2)
  const [currentFrame1, setCurrentFrame1] = useState(0);
  const [currentFrame2, setCurrentFrame2] = useState(0);
  const [frames1Loaded, setFrames1Loaded] = useState(false);
  const [frames2Loaded, setFrames2Loaded] = useState(false);

  // Refs for sections
  const section1Ref = useRef(null);
  const section2Ref = useRef(null);
  const section3Ref = useRef(null);
  const section4Ref = useRef(null);

  // Data helpers
  const lines = [...new Set(partListData.map(item => item.Line))].sort();
  const selectedPartData = availableParts.find(p => p.SKU.toString() === selectedPart);

  // ---- Dimensions listener ----
  useEffect(() => {
    const update = () => setDimensions({ width: window.innerWidth, height: window.innerHeight });
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);

  // ---- Build available parts when line changes ----
  useEffect(() => {
    if (!selectedLine) {
      setAvailableParts([]);
      setSelectedPart('');
      return;
    }
    const parts = partListData
      .filter(item => item.Line === selectedLine)
      .map(item => ({
        SKU: item.SKU,
        'Carton Qty': item['Carton Qty'],
        'Unit Weight (lb)': item['Unit Weight (lb)'],
        'Price (ea)': item['Price (ea)']
      }));
    setAvailableParts(parts);
    setSelectedPart('');
  }, [selectedLine]);

  // ---- Validate form for submit button ----
  useEffect(() => {
    const ok =
      selectedLine &&
      selectedPart &&
      production &&
      parseInt(production) > 0 &&
      parseInt(production) <= 15000;
    setShowSubmitButton(ok);
  }, [selectedLine, selectedPart, production]);

  // Frame paths for animations
  const BASE_PATH = window.location.hostname === 'localhost' ? '' : process.env.PUBLIC_URL;
  const BOX_DIR = `${BASE_PATH}/assets/boxframes`;
  const CAR_DIR = `${BASE_PATH}/assets/carframes`;
  const BOX_FRAME_COUNT = 49;
  const CAR_FRAME_COUNT = 49;
  
  // Generate frame paths
  const boxFrames = Array.from({ length: BOX_FRAME_COUNT }, (_, i) => 
    `frame_${i.toString().padStart(3, '0')}.png`
  );
  const carFrames = Array.from({ length: CAR_FRAME_COUNT }, (_, i) => 
    `frame_${i.toString().padStart(3, '0')}.png`
  );

  useEffect(() => {
    // preload Section 1 frames
    const preload1 = async () => {
      const promises = [];
      for (let i = 1; i <= BOX_FRAME_COUNT; i++) {
        const num = (i - 1).toString().padStart(3, '0');
        const img = new Image();
        img.src = `${BOX_DIR}/frame_${num}.png`;
        promises.push(
          new Promise((res, rej) => {
            img.onload = res;
            img.onerror = rej;
          })
        );
      }
      try { await Promise.all(promises); } catch { /* still continue */ }
      setFrames1Loaded(true);
    };
    // preload Section 2 frames
    const preload2 = async () => {
      const promises = [];
      for (let i = 1; i <= CAR_FRAME_COUNT; i++) {
        const num = (i - 1).toString().padStart(3, '0');
        const img = new Image();
        img.src = `${CAR_DIR}/frame_${num}.png`;
        promises.push(
          new Promise((res, rej) => {
            img.onload = res;
            img.onerror = rej;
          })
        );
      }
      try { await Promise.all(promises); } catch { /* still continue */ }
      setFrames2Loaded(true);
    };

    preload1();
    preload2();
  }, []); // once

  // ---- Submit handler: jump to Section 1 ----
  const handleSubmit = (e) => {
    e.preventDefault();
    setShowScrollMessage(true);
    setTimeout(() => {
      const firstSection = document.getElementById('section-1');
      if (firstSection) firstSection.scrollIntoView({ behavior: 'smooth' });
    }, 300);
  };

  // ---- Computations for text displays ----
  const parsePrice = (s) => s ? parseFloat(s.replace(/[^0-9.]/g, '')) : 0;
  const parseWeight = (s) => s ? parseFloat(s.replace(/[^0-9.]/g, '')) : 0;

  const prodCount = parseInt(production || '0', 10) || 0;
  const cartonQty = selectedPartData ? parseInt(selectedPartData['Carton Qty'], 10) || 1 : 1;
  const unitWeight = selectedPartData ? parseWeight(selectedPartData['Unit Weight (lb)']) : 0;
  const unitPrice = selectedPartData ? parsePrice(selectedPartData['Price (ea)']) : 0;

  const totalBoxes = cartonQty ? Math.ceil(prodCount / cartonQty) : 0;
  const totalWeightLbs = unitWeight * prodCount;
  const retailValue = unitPrice * prodCount;

  // Cars equivalent (Section 2)
  const SMALL_CAR_LBS = 2800;
  const carEquivalent = totalWeightLbs > 0 ? (totalWeightLbs / SMALL_CAR_LBS) : 0;

  // Section 4: 4-bar chart calculations
  const wageRate = 21; // $21/hour
  const wage = wageRate * 8; // 8 hour shift
  const steelPricePerLb = 0.54; // July 2024 galvanized steel coil price
  const steelCost = unitWeight * prodCount * steelPricePerLb;
  const companyProfit = Math.max(0, retailValue - (wage + steelCost));

  // ---- ScrollTriggers ----
  // Section 1: frame scrub + pin
  useEffect(() => {
    if (!showScrollMessage || !section1Ref.current) return;

    const st = ScrollTrigger.create({
      trigger: section1Ref.current,
      start: 'top top',
      end: '+=175%',
      pin: true,
      scrub: 1,
      onEnter: () => gsap.set(section1Ref.current, { opacity: 1, y: 0 }),
      onUpdate: (self) => {
        const idx = Math.min(
          BOX_FRAME_COUNT - 1,
          Math.max(0, Math.floor(self.progress * (BOX_FRAME_COUNT - 1)))
        );
        setCurrentFrame1(idx);
      },
      onLeave: () => {
        const next = section2Ref.current;
        if (next) gsap.to(window, { duration: 0.6, ease: 'power2.out', scrollTo: next });
      },
      onLeaveBack: () => {
        // Section 1 is first, no previous section
      }
    });

    return () => st.kill();
  }, [showScrollMessage]);

  // Section 2: frame scrub + pin
  useEffect(() => {
    if (!showScrollMessage || !section2Ref.current) return;

    const st = ScrollTrigger.create({
      trigger: section2Ref.current,
      start: 'top top',
      end: '+=175%',
      pin: true,
      scrub: 1,
      onEnter: () => gsap.set(section2Ref.current, { opacity: 1, y: 0 }),
      onUpdate: (self) => {
        const idx = Math.min(
          CAR_FRAME_COUNT - 1,
          Math.max(0, Math.floor(self.progress * (CAR_FRAME_COUNT - 1)))
        );
        setCurrentFrame2(idx);
      },
      onLeave: () => {
        const next = section3Ref.current;
        if (next) gsap.to(window, { duration: 0.6, ease: 'power2.out', scrollTo: next });
      },
      onLeaveBack: () => {
        const prev = section1Ref.current;
        if (prev) gsap.to(window, { duration: 0.6, ease: 'power2.out', scrollTo: prev });
      }
    });

    return () => st.kill();
  }, [showScrollMessage]);

  // Section 3: Lottie cash rain (scrub with scroll, pin section)
  useEffect(() => {
    if (!showScrollMessage || !section3Ref.current) return;

    let anim;
    let cancelled = false;

    (async () => {
      try {
        // Load JSON from public/assets to be GH Pages friendly
        const response = await fetch(`${process.env.PUBLIC_URL}/assets/cashrain.json`);
        const data = await response.json();
        if (cancelled) return;

        const container = section3Ref.current.querySelector('.lottie-container');
        if (!container) return;

        anim = lottie.loadAnimation({
          container,
          renderer: 'svg',
          loop: false,
          autoplay: false,
          animationData: data
        });

        // Store reference on the node for the ScrollTrigger callback
        section3Ref.current.lottieAnimation = anim;

        const onDomLoaded = () => ScrollTrigger.refresh();
        anim.addEventListener('DOMLoaded', onDomLoaded);

        const st = ScrollTrigger.create({
          trigger: section3Ref.current,
          start: 'top top',
          end: '+=175%',
          pin: true,
          scrub: 1,
          onEnter: () => gsap.set(section3Ref.current, { opacity: 1, y: 0 }),
          onUpdate: (self) => {
            if (!section3Ref.current || !section3Ref.current.lottieAnimation) return;
            const a = section3Ref.current.lottieAnimation;
            const frame = Math.floor(self.progress * (a.totalFrames - 1));
            a.goToAndStop(frame, true);
          },
          onLeave: () => {
            const next = section4Ref.current;
            if (next) gsap.to(window, { duration: 0.6, ease: 'power2.out', scrollTo: next });
          },
          onLeaveBack: () => {
            const prev = section2Ref.current;
            if (prev) gsap.to(window, { duration: 0.6, ease: 'power2.out', scrollTo: prev });
          }
        });

        // Cleanup
        return () => {
          anim?.removeEventListener('DOMLoaded', onDomLoaded);
          anim?.destroy();
          st?.kill();
        };
      } catch (e) {
        // If loading fails, still allow section to render
        // eslint-disable-next-line no-console
        console.error('Lottie load error:', e);
      }
    })();

    return () => {
      cancelled = true;
      if (anim) anim.destroy();
    };
  }, [showScrollMessage]);

  // Section 4: 4-bar chart animation (autoplay once, NOT pinned)
  useEffect(() => {
    if (!showScrollMessage || !section4Ref.current) return;

    // Find the maximum value to scale bars proportionally
    const maxValue = Math.max(wage, steelCost, retailValue, companyProfit);
    
    // Calculate percentages for each bar (minimum 8% for visibility)
    const wagePercent = maxValue > 0 ? Math.max((wage / maxValue) * 100, 8) : 8;
    const steelPercent = maxValue > 0 ? Math.max((steelCost / maxValue) * 100, 8) : 8;
    const retailPercent = maxValue > 0 ? Math.max((retailValue / maxValue) * 100, 8) : 8;
    const profitPercent = maxValue > 0 ? Math.max((companyProfit / maxValue) * 100, 8) : 8;

    const st = ScrollTrigger.create({
      trigger: section4Ref.current,
      start: 'top 80%',
      once: true,
      onEnter: () => {
        // Animate all bars together with staggered timing
        gsap.to('#wage-bar', {
          height: `${wagePercent}%`,
          duration: 1.2,
          ease: 'power2.out',
          onUpdate: () => {
            const el = document.getElementById('wage-label');
            if (el) el.innerText = `$${Math.round(wage).toLocaleString()}`;
          }
        });

        gsap.to('#steel-bar', {
          height: `${steelPercent}%`,
          duration: 1.4,
          ease: 'power2.out',
          delay: 0.2,
          onUpdate: () => {
            const el = document.getElementById('steel-label');
            if (el) el.innerText = `$${Math.round(steelCost).toLocaleString()}`;
          }
        });

        gsap.to('#retail-bar', {
          height: `${retailPercent}%`,
          duration: 1.6,
          ease: 'power2.out',
          delay: 0.4,
          onUpdate: () => {
            const el = document.getElementById('retail-label');
            if (el) el.innerText = `$${Math.round(retailValue).toLocaleString()}`;
          }
        });

        gsap.to('#profit-bar', {
          height: `${profitPercent}%`,
          duration: 1.8,
          ease: 'power2.out',
          delay: 0.6,
          onUpdate: () => {
            const el = document.getElementById('profit-label');
            if (el) el.innerText = `$${Math.round(companyProfit).toLocaleString()}`;
          }
        });
      }
    });

    return () => st.kill();
  }, [showScrollMessage, wage, steelCost, retailValue, companyProfit]);

  // ---- Render ----
  return (
    <div className="min-h-screen" style={{ backgroundColor: 'rgba(242,238,235,1)' }}>
      {/* Header */}
      <div className="shadow-sm" style={{ backgroundColor: 'rgba(242,238,235,1)' }}>
        <div className="max-w-md mx-auto px-4 py-8">
          <h1 className="text-3xl font-bold text-gray-900 text-center mb-4">
            Workload Stats
          </h1>
          <p className="text-gray-600 text-center text-sm leading-relaxed">
            Track your daily production and see the real impact of your work.
          </p>
        </div>
      </div>

      {/* Form */}
      <div className="max-w-md mx-auto px-4 py-8">
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Line */}
          <div>
            <label htmlFor="line" className="block text-sm font-medium text-gray-700 mb-2">
              Select Line
            </label>
            <select
              id="line"
              value={selectedLine}
              onChange={(e) => setSelectedLine(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            >
              <option value="">Choose a line...</option>
              {lines.map(line => (
                <option key={line} value={line}>{line}</option>
              ))}
            </select>
          </div>

          {/* Part */}
          {selectedLine && (
            <div>
              <label htmlFor="part" className="block text-sm font-medium text-gray-700 mb-2">
                Select Part
              </label>
              <select
                id="part"
                value={selectedPart}
                onChange={(e) => setSelectedPart(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">Choose a part...</option>
                {availableParts.map(part => (
                  <option key={part.SKU} value={part.SKU}>
                    TP{part.SKU}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Production */}
          {selectedPart && (
            <div>
              <label htmlFor="production" className="block text-sm font-medium text-gray-700 mb-2">
                Production Count
              </label>
              <input
                type="number"
                id="production"
                value={production}
                onChange={(e) => setProduction(e.target.value)}
                min="1"
                max="15000"
                placeholder="Enter production count"
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              />
            </div>
          )}

          {/* Submit */}
          {showSubmitButton && (
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 px-4 rounded-md font-medium hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 transition-colors"
            >
              Calculate My Stats
            </button>
          )}

          {/* Scroll hint */}
          {showScrollMessage && (
            <div className="text-center py-4">
              <p className="text-green-700 font-medium animate-pulse">
                📊 Scroll down to see your results!
              </p>
            </div>
          )}
        </form>
      </div>

      {/* Results */}
      {showScrollMessage && (
        <>
          {/* Section 1: Boxes Stacked (frame scrub) */}
          <div
            id="section-1" ref={section1Ref} className="h-screen w-full flex items-center justify-center relative overflow-hidden"
            style={{ backgroundColor: 'rgba(242,238,235,1)' }}
          >
            {/* PixiCanvas */}
            <div className="absolute inset-0 z-0">
              <PixiCanvas 
                width={window.innerWidth} 
                height={window.innerHeight}
                frames={boxFrames}
                frameDir={BOX_DIR}
                frameIndex={currentFrame1}
              />
            </div>

            {/* Gradient scrim */}
            <div className="absolute inset-0 bg-gradient-to-b from-black/35 via-transparent to-black/20 pointer-events-none z-0" />

            {/* Text */}
            <div className="relative z-10">
              <div className="inline-block px-3 py-2 rounded-xl bg-black/40 backdrop-blur-sm">
                <h2 className="text-white font-bold tracking-tight text-4xl md:text-6xl" style={{ WebkitTextStroke: '1px rgba(0,0,0,0.55)' }}>
                  Your Production in Boxes
                </h2>
                <p className="text-white/90 text-lg mt-2">
                  You stacked {totalBoxes} boxes ({prodCount.toLocaleString()} parts • {Math.round(totalWeightLbs).toLocaleString()} lbs total)
                </p>
              </div>
            </div>
          </div>

          {/* Section 2: Weight Comparison (frame scrub) */}
          <div
            ref={section2Ref}
            id="section-2"
            className="h-screen w-full flex items-center justify-center relative overflow-hidden"
            style={{ backgroundColor: 'rgba(242,238,235,1)' }}
          >
            {/* Frame image */}
            {frames2Loaded && (
              <img
                src={`${CAR_DIR}/frame_${currentFrame2.toString().padStart(3, '0')}.png`}
                alt={`Frame ${currentFrame2 + 1}`}
                className="absolute inset-0 m-auto max-w-full max-h-full object-contain z-0"
              />
            )}

            {/* Gradient scrim */}
            <div className="absolute inset-0 bg-gradient-to-b from-black/35 via-transparent to-black/20 pointer-events-none z-0" />

            {/* Text */}
            <div className="text-center px-4 relative z-10">
              <div className="inline-block px-3 py-2 rounded-xl bg-black/40 backdrop-blur-sm">
                <h2 className="text-white font-bold tracking-tight text-4xl md:text-6xl" style={{ WebkitTextStroke: '1px rgba(0,0,0,0.55)' }}>
                  That equals {Math.round(totalWeightLbs).toLocaleString()} lbs
                </h2>
                <p className="text-emerald-100 text-lg mt-2">
                  (like lifting {carEquivalent.toFixed(1)} small cars)
                </p>
              </div>
            </div>
          </div>

          {/* Section 3: Retail Value (Lottie scrub) */}
          <div
            ref={section3Ref}
            id="section-3"
            className="h-screen w-full flex items-center justify-center relative overflow-hidden"
            style={{ backgroundColor: 'rgba(242,238,235,1)' }}
          >
            {/* Lottie container */}
            <div className="absolute inset-0 lottie-container pointer-events-none z-0" />

            {/* Gradient scrim */}
            <div className="absolute inset-0 bg-gradient-to-b from-black/35 via-transparent to-black/20 pointer-events-none z-0" />

            {/* Text */}
            <div className="text-center px-4 relative z-10">
              <div className="inline-block px-3 py-2 rounded-xl bg-black/40 backdrop-blur-sm">
                <h2 className="text-white font-bold tracking-tight text-4xl md:text-6xl" style={{ WebkitTextStroke: '1px rgba(0,0,0,0.55)' }}>
                  Retail value: ${Math.round(retailValue).toLocaleString()}
                </h2>
                <p className="text-white/90 text-lg mt-2">
                  That's the value you helped create.
                </p>
              </div>
            </div>
          </div>

          {/* Section 4: Wage vs Retail (autoplay bars) */}
          <div
            ref={section4Ref}
            id="section-4"
            className="h-screen w-full flex flex-col items-center justify-center relative overflow-hidden"
            style={{ backgroundColor: 'rgba(242,238,235,1)' }}
          >
            {/* Gradient scrim */}
            <div className="absolute inset-0 bg-gradient-to-b from-black/35 via-transparent to-black/20 pointer-events-none z-0" />

            <div className="relative z-10">
              <div className="inline-block px-3 py-2 rounded-xl bg-black/40 backdrop-blur-sm mb-8">
                <h2 className="text-white font-bold tracking-tight text-4xl md:text-6xl" style={{ WebkitTextStroke: '1px rgba(0,0,0,0.55)' }}>
                  Production Value Breakdown
                </h2>
              </div>
            </div>

            {/* Value Summary Text */}
            <div className="relative z-10 mb-8">
              <div className="inline-block px-4 py-3 rounded-xl bg-black/40 backdrop-blur-sm">
                <div className="grid grid-cols-2 gap-4 text-white text-sm md:text-base">
                  <div>Your estimated wage: <span className="font-bold text-blue-300">${Math.round(wage).toLocaleString()}</span></div>
                  <div>Estimated steel cost: <span className="font-bold text-gray-300">${Math.round(steelCost).toLocaleString()}</span></div>
                  <div>Retail value: <span className="font-bold text-green-300">${Math.round(retailValue).toLocaleString()}</span></div>
                  <div>Company profit: <span className="font-bold text-orange-300">${Math.round(companyProfit).toLocaleString()}</span></div>
                </div>
              </div>
            </div>

            <div className="flex items-end gap-8 h-[50%] w-[90%] max-w-4xl relative z-10">
              {/* Wage Column */}
              <div className="h-full flex flex-col justify-end items-center flex-1">
                <div id="wage-bar" className="w-16 bg-blue-600 rounded-t-lg" style={{ height: 0 }} />
                <p id="wage-label" className="mt-3 text-sm font-semibold text-blue-800">$0</p>
                <p className="text-xs text-gray-700 text-center">Your Wage</p>
              </div>

              {/* Steel Cost Column */}
              <div className="h-full flex flex-col justify-end items-center flex-1">
                <div id="steel-bar" className="w-16 bg-gray-600 rounded-t-lg" style={{ height: 0 }} />
                <p id="steel-label" className="mt-3 text-sm font-semibold text-gray-800">$0</p>
                <p className="text-xs text-gray-700 text-center">Steel Cost</p>
              </div>

              {/* Retail Value Column */}
              <div className="h-full flex flex-col justify-end items-center flex-1">
                <div id="retail-bar" className="w-16 bg-green-600 rounded-t-lg" style={{ height: 0 }} />
                <p id="retail-label" className="mt-3 text-sm font-semibold text-green-800">$0</p>
                <p className="text-xs text-gray-700 text-center">Retail Value</p>
              </div>

              {/* Company Profit Column */}
              <div className="h-full flex flex-col justify-end items-center flex-1">
                <div id="profit-bar" className="w-16 bg-orange-600 rounded-t-lg" style={{ height: 0 }} />
                <p id="profit-label" className="mt-3 text-sm font-semibold text-orange-800">$0</p>
                <p className="text-xs text-gray-700 text-center">Company Profit</p>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export default App;
